-- Tax cell (tax), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA tax;

CREATE FUNCTION tax.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE tax.tax_items (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    tax_year                 integer NOT NULL CHECK (tax_year >= 2000),
    jurisdiction             text NOT NULL DEFAULT 'TH' CHECK (length(jurisdiction) <= 12),
    tax_type                 text NOT NULL CHECK (tax_type IN ('income', 'vat', 'withholding', 'property', 'social_security', 'other')),
    period_start             date,
    period_end               date,
    amount_due               double precision CHECK (amount_due IS NULL OR (amount_due >= 0)),
    amount_paid              double precision NOT NULL DEFAULT 0 CHECK (amount_paid >= 0),
    currency                 text NOT NULL DEFAULT 'THB' CHECK (length(currency) <= 12),
    due_date                 date,
    status                   text NOT NULL DEFAULT 'estimated' CHECK (status IN ('estimated', 'open', 'filed', 'paid', 'waived', 'overdue')),
    evidence_ref             text,
    metadata                 jsonb CHECK (metadata IS NULL OR (jsonb_typeof(metadata) = 'object')),
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX tax_items_legacy ON tax.tax_items (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX tax_items_status ON tax.tax_items (workspace_id, status);
CREATE INDEX tax_items_tax_type ON tax.tax_items (workspace_id, tax_type);
CREATE INDEX tax_items_tax_year ON tax.tax_items (workspace_id, tax_year);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE tax.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('tax-item')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE tax.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON tax.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['tax_items', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE tax.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE tax.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON tax.%I'
                       ' USING (workspace_id = tax.current_workspace())'
                       ' WITH CHECK (workspace_id = tax.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA tax TO tax_api;
GRANT EXECUTE ON FUNCTION tax.current_workspace() TO tax_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON tax.tax_items TO tax_api;
GRANT USAGE ON SEQUENCE tax.tax_items_id_seq TO tax_api;
GRANT SELECT, INSERT ON tax.create_keys TO tax_api;
GRANT SELECT, INSERT ON tax.outbox TO tax_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON tax.outbox TO tax_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON tax.outbox TO tax_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA tax TO tax_publisher;
GRANT SELECT ON tax.outbox TO tax_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON tax.outbox TO tax_publisher;
